const MOD = 1000000007;
const K = 1010;

function powmod(a, x) {
    let res = 1;
    a %= MOD;
    while (x > 0) {
        if (x & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        x >>= 1;
    }
    return res;
}

const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
const k = parseInt(input[0]);
const va = parseInt(input[1]);
const vb = parseInt(input[2]);

const den = powmod(va + vb, MOD - 2);
const pa = (va * den) % MOD;
const pb = (vb * den) % MOD;
const one_b = (pa * powmod(pb, MOD - 2)) % MOD;

const dp = Array.from({ length: K }, () => Array(K).fill(0));

for (let i = k - 1; i >= 0; i--) {
    for (let j = k; j >= 1; j--) {
        if (i + j >= k) {
            dp[i][j] = (i + j + one_b) % MOD;
        } else {
            dp[i][j] = (pa * dp[i][j + 1] + pb * dp[i + j][j]) % MOD;
        }
    }
}

console.log(dp[0][1]);

