const K = 1010;

function powmod(a, x) {
    if (x === 0n) return 1n;
    if (x % 2n === 0n) {
        const half = powmod(a, x / 2n);
        return (half * half) % MOD;
    }
    return (a * powmod(a, x - 1n)) % MOD;
}

const fs = require('fs');
const input = fs.readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
