const vb_b = BigInt(vb);

const den = powmod(va_b + vb_b, MOD - 2n);
const pa = (va_b * den) % MOD;
const pb = (vb_b * den) % MOD;
const one_b = (pa * powmod(pb, MOD - 2n)) % MOD;

const dp = Array.from({ length: K }, () => Array(K).fill(0n));

for (let i = k - 1; i >= 0; i--) {
    for (let j = k; j >= 1; j--) {
        const i_b = BigInt(i);
