const MOD = 1000000007n;
const K = 1010;

function powmod(a, x) {
    let res = 1n;
    a %= MOD;
    while (x > 0n) {
        if (x & 1n) res = (res * a) % MOD;
        a = (a * a) % MOD;
        x >>= 1n;
    }
    return res;
}

const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/);
const k = parseInt(input[0]);
const va = BigInt(parseInt(input[1]));
const vb = BigInt(parseInt(input[2]));

