const pa = (va * den) % MOD;
const pb = (vb * den) % MOD;
const one_b = (pa * powmod(pb, MOD - 2n)) % MOD;

const dp = Array.from({ length: K }, () => Array(K).fill(0n));

for (let i = k - 1; i >= 0; i--) {
    for (let j = k; j >= 1; j--) {
        if (i + j >= k) {
            dp[i][j] = (BigInt(i + j) + one_b) % MOD;
        } else {
            dp[i][j] = (pa * dp[i][j + 1] + pb * dp[i + j][j]) % MOD;
        }
    }
}

